/**
 * A rectangle used for scrolling into view.
 *
 * @public
 * @unofficial
 */
export interface Cm5EditorScrollRect {
  /** The bottom coordinate in pixels. */
  bottom: number;
  /** The left coordinate in pixels. */
  left: number;
  /** The right coordinate in pixels. */
  right: number;
  /** The top coordinate in pixels. */
  top: number;
}
